	private static void assertMaterializationBounds(Measured result) {
		assertThat(result.quote.low(Feature.OUTPUT_MATERIALIZATION))
				.as("physical low must not exceed measured BindingSet allocations")
				.isLessThanOrEqualTo(result.allocations);
		assertThat(result.quote.high(Feature.OUTPUT_MATERIALIZATION))
				.as("physical high must cover measured BindingSet allocations")
				.isGreaterThanOrEqualTo(result.allocations);
	}

	private static Measured measure(double sample, long offset, long limit, boolean knownPopulation) throws Exception {
		return measure(sample, offset, limit, knownPopulation, false);
	}

	private static Measured measure(double sample, long offset, long limit, boolean knownPopulation, boolean merge)
			throws Exception {
		try (Fixture fixture = new Fixture(sample, knownPopulation, merge)) {
			double expectedRows = sample * FANOUT;
			assertThat(LmdbNativeWork.rowsOut(fixture.join, fixture.row, 0L)).isEqualTo(expectedRows);
			double demand = limit < 0L ? -1D : (double) (offset + limit);
			LmdbNativeCostVector producerFeatures;
			try (LmdbNativeStrategyProposal<BatchCursor> producer = fixture.join.proposeBatch(fixture.row, CAPACITY)) {
				assertThat(producer).isNotNull();
				LmdbNativeCostQuote quote = producer.costQuote();
				assertThat(quote.outputRows()).isEqualTo(expectedRows);
				assertThat(quote.ordered()).isFalse();
				assertThat(quote.distinct()).isFalse();
				assertThat(quote.total().high(Feature.OUTPUT_MATERIALIZATION))
						.as("the native ID producer leaves BindingSet creation to its root consumer")
						.isZero();
				producerFeatures = quote.forSlice(demand);
			}

			List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
			LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
				assertThat(id).isEqualTo(ROUTE);
				selected.add(
						record.entries().stream().filter(entry -> entry.id().equals(id)).findFirst().orElseThrow());
			});
			Map<List<Value>, Long> bag = new LinkedHashMap<>();
			Set<BindingSet> identities = Collections.newSetFromMap(new IdentityHashMap<>());
			long createdBefore = NativeProjectedBindingSet.CREATED.get();
			long buildsBefore = LmdbNativeHashJoin.BUILDS.get();
			long mergesBefore = LmdbNativeMergeJoin.JOINS.get();
			long batchesBefore = NativeBatch.ROOT_ITERATIONS.get();
			int returned = 0;
			try (NativeRowsIteration rows = new NativeRowsIteration(fixture.step(offset, limit), fixture.evaluation,
					EmptyBindingSet.getInstance())) {
				while (rows.hasNext()) {
					BindingSet answer = rows.next();
					assertThat(answer).isInstanceOf(NativeProjectedBindingSet.class);
					assertThat(answer.getBindingNames()).containsExactlyInAnyOrder("a", "c");
					assertThat(identities.add(answer)).as("ordinary batch rows do not reuse a factorized BindingSet")
							.isTrue();
					bag.merge(List.of(answer.getValue("a"), answer.getValue("c")), 1L, Long::sum);
					returned++;
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(bag).isEqualTo(expectedBag(offset, limit));
			assertThat(identities).hasSize(returned);
			long allocations = NativeProjectedBindingSet.CREATED.get() - createdBefore;
			assertThat(allocations).as("the actual immutable projected-BindingSet constructor count")
					.isEqualTo(returned);
			assertThat(fixture.source.statementCloses).isEqualTo(fixture.source.statementOpens);
			if (limit == 0L) {
				assertThat(selected).isEmpty();
				assertThat(fixture.source.statementOpens).isZero();
				assertThat(LmdbNativeHashJoin.BUILDS.get() - buildsBefore).isZero();
				assertThat(NativeBatch.ROOT_ITERATIONS.get() - batchesBefore).isZero();
				return new Measured(null, returned, bag.size(), allocations);
			}
			assertThat(selected).as("one successful open, not merely an offered quote").hasSize(1);
			assertThat(LmdbNativeHashJoin.BUILDS.get() - buildsBefore).isEqualTo(merge ? 0L : 1L);
			assertThat(LmdbNativeMergeJoin.JOINS.get() - mergesBefore).isEqualTo(merge ? 1L : 0L);
			assertThat(NativeBatch.ROOT_ITERATIONS.get() - batchesBefore).isEqualTo(1L);
			assertThat(fixture.source.statementOpens).isEqualTo(2);
			assertThat(fixture.source.rootRows).isPositive();
			if (!merge) {
				assertThat(fixture.source.rootRows).as("the hash build completes before any probe output")
						.isEqualTo(ROOT_ROWS);
			}
			assertThat(fixture.source.tailRows).isPositive();
			if (limit < 0L || offset + limit >= OUTPUT_ROWS) {
				assertThat(fixture.source.rootRows).isEqualTo(ROOT_ROWS);
				assertThat(fixture.source.tailRows).isEqualTo(OUTPUT_ROWS);
			}
			LmdbNativeCostVector actual = selected.getFirst().features();
			assertThat(actual).isNotNull();
			assertThat(actual.expected(Feature.OUTPUT_MATERIALIZATION))
					.as("the sample and logical LIMIT+OFFSET demand remain unchanged")
					.isEqualTo(demand < 0D ? expectedRows : Math.min(demand, expectedRows));
			for (Feature feature : Feature.values()) {
				if (feature != Feature.OUTPUT_MATERIALIZATION) {
					assertThat(actual.low(feature)).as("%s producer low", feature)
							.isEqualTo(producerFeatures.low(feature));
					assertThat(actual.expected(feature)).as("%s producer expectation", feature)
							.isEqualTo(producerFeatures.expected(feature));
					assertThat(actual.high(feature)).as("%s producer high", feature)
							.isEqualTo(producerFeatures.high(feature));
				}
			}
			return new Measured(actual, returned, bag.size(), allocations);
		}
	}

	private static Map<List<Value>, Long> expectedBag(long offset, long limit) {
		List<List<Value>> rows = new ArrayList<>();
		for (int subject = 0; subject < SUBJECTS; subject++) {
			for (int middle = 0; middle < MIDDLES; middle++) {
				for (int value = 0; value < FANOUT; value++) {
					rows.add(List.of(value(100L + subject), value(2_000L + subject * FANOUT + value)));
				}
			}
		}
		Map<List<Value>, Long> expected = new LinkedHashMap<>();
		rows.stream()
				.skip(offset)
				.limit(limit < 0L ? Long.MAX_VALUE : limit)
				.forEach(row -> expected.merge(row, 1L, Long::sum));
		return expected;
	}

	private static Value value(long id) {
		return SimpleValueFactory.getInstance().createIRI(NS + id);
	}

