	private static final class CountingSource implements NativeLmdbQuerySource {
		final List<long[]> data = new ArrayList<>();
		final boolean knownPopulation;
		int statementOpens, statementCloses, rootRows, tailRows;

		CountingSource(boolean knownPopulation) {
			this.knownPopulation = knownPopulation;
			for (int subject = 0; subject < SUBJECTS; subject++) {
				for (int middle = 0; middle < MIDDLES; middle++) {
					long key = 1_000L + subject * MIDDLES + middle;
					data.add(new long[] { 100L + subject, ROOT, key, 0L });
					for (int value = 0; value < FANOUT; value++) {
						data.add(new long[] { key, TAIL, 2_000L + subject * FANOUT + value, 0L });
					}
				}
			}
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		@Override
		public long idOf(Value value) {
			return value.stringValue().startsWith(NS)
					? Long.parseLong(value.stringValue().substring(NS.length()))
					: UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			return value(id);
		}

		@Override
		public IndexAccessProfile indexAccessProfile() {
			return knownPopulation ? coveringProfile(data.size()) : null;
		}

		@Override
		public OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			long rows = data.stream().filter(record -> record[1] == predicate).count();
			long keys = keys(predicate, bySubject);
			return OptionalDouble.of(keys == 0L ? 0D : (double) rows / keys);
		}

		@Override
		public OptionalDouble distinctFanOutKeys(long predicate, boolean bySubject) {
			return OptionalDouble.of(keys(predicate, bySubject));
		}

		@Override
		public OptionalLong adjacencyKeyDomainCardinality(long predicate, boolean bySubject) {
			return OptionalLong.of(keys(predicate, bySubject));
		}

		private long keys(long predicate, boolean bySubject) {
			return data.stream()
					.filter(record -> record[1] == predicate)
					.mapToLong(record -> record[bySubject ? 0 : 2])
					.distinct()
					.count();
		}

		private List<long[]> matches(long s, long p, long o, long c) {
			return data.stream()
					.filter(q -> (s == UNKNOWN_ID || s == q[0]) && (p == UNKNOWN_ID || p == q[1])
							&& (o == UNKNOWN_ID || o == q[2]) && (c == UNKNOWN_ID || c == q[3]))
					.toList();
		}

		@Override
		public String indexName(StatementOrder order, long s, long p, long o, long c) {
			return order == StatementOrder.O ? "opsc" : order == StatementOrder.S ? "spoc" : "";
		}

		@Override
		public RecordIterator statements(StatementOrder order, long s, long p, long o, long c) {
			assertThat(order).isIn(StatementOrder.S, StatementOrder.O);
			int key = order == StatementOrder.O ? 2 : 0;
			return iterator(
					matches(s, p, o, c).stream().sorted(Comparator.comparingLong(record -> record[key])).toList());
		}

		@Override
		public RecordIterator statements(long s, long p, long o, long c) {
			return iterator(matches(s, p, o, c));
		}

		private RecordIterator iterator(List<long[]> matches) {
			statementOpens++;
			return new RecordIterator() {
				int index;
				boolean closed;

				@Override
				public long[] next() {
					if (index >= matches.size()) {
						return null;
					}
					long[] record = matches.get(index++);
					if (record[1] == ROOT) {
						rootRows++;
					} else if (record[1] == TAIL) {
						tailRows++;
					}
					return record;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						statementCloses++;
					}
				}
			};
		}

		@Override
		public long count(long s, long p, long o, long c) {
			return matches(s, p, o, c).size();
		}

		@Override
		public boolean has(long s, long p, long o, long c) {
			return !matches(s, p, o, c).isEmpty();
		}

		@Override
		public double estimate(long s, long p, long o, long c) {
			return count(s, p, o, c);
		}
	}
